code.cpp:
class Solution {
public:
    int searchInsert(vector<int>& nums, int target) {
        int low = 0;
        int high = static_cast<int>(nums.size());
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (nums[mid] < target) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
};
